// vendor_slice_tb.sv (brief 151): xsim testbench for AMD's AXI Register Slice IP (module vs_dut, generated by the queued run),
// AW channel only: latency, throughput and bubbles of the mode that was generated. Prints one line:
//   RESULT latency=<clocks> throughput_per_100=<beats per 100 clocks, always valid and ready> bubbles_after_stall=<idle output
//   clocks in the clock window after the sink releases a stalled stream>
// NOT RUN YET. Latency is counted as the library counts it: from the edge that accepts a beat into an empty slice to the first clock
// it is visible at the master port (1 for one register stage).
`timescale 1ns/1ps
module vendor_slice_tb;
    logic aclk = 0, aresetn = 0;
    always #5 aclk = ~aclk;
    logic        s_awvalid = 0, s_awready, m_awvalid, m_awready = 0;
    logic [31:0] s_awaddr = 0, m_awaddr;
    logic [2:0]  s_awprot = 0, m_awprot;
    // the other four channels are tied off
    vs_dut dut (.aclk, .aresetn,
        .s_axi_awaddr(s_awaddr), .s_axi_awprot(s_awprot), .s_axi_awvalid(s_awvalid), .s_axi_awready(s_awready),
        .m_axi_awaddr(m_awaddr), .m_axi_awprot(m_awprot), .m_axi_awvalid(m_awvalid), .m_axi_awready(m_awready),
        .s_axi_wdata(32'd0), .s_axi_wstrb(4'd0), .s_axi_wvalid(1'b0), .s_axi_wready(), .m_axi_wdata(), .m_axi_wstrb(), .m_axi_wvalid(), .m_axi_wready(1'b1),
        .s_axi_bresp(), .s_axi_bvalid(), .s_axi_bready(1'b1), .m_axi_bresp(2'b00), .m_axi_bvalid(1'b0), .m_axi_bready(),
        .s_axi_araddr(32'd0), .s_axi_arprot(3'd0), .s_axi_arvalid(1'b0), .s_axi_arready(), .m_axi_araddr(), .m_axi_arprot(), .m_axi_arvalid(), .m_axi_arready(1'b1),
        .s_axi_rdata(), .s_axi_rresp(), .s_axi_rvalid(), .s_axi_rready(1'b1), .m_axi_rdata(32'd0), .m_axi_rresp(2'b00), .m_axi_rvalid(1'b0), .m_axi_rready());
    integer t, lat, acc_t, out_beats, i, bubbles;
    initial begin
        repeat (4) @(posedge aclk); aresetn <= 1; repeat (3) @(posedge aclk);
        // latency: one beat, sink ready
        m_awready <= 1; s_awvalid <= 1; s_awaddr <= 32'h1;
        acc_t = -1; lat = -1;
        for (t = 0; t < 20; t++) begin
            @(negedge aclk);
            if (acc_t < 0 && s_awvalid && s_awready) acc_t = t;
            if (lat < 0 && m_awvalid) lat = t - acc_t;
            @(posedge aclk);
            if (acc_t >= 0 && t >= acc_t) s_awvalid <= 0;
        end
        // throughput: always valid, always ready, 100 clocks
        out_beats = 0; s_awvalid <= 1;
        for (t = 0; t < 100; t++) begin
            @(posedge aclk); s_awaddr <= s_awaddr + 1;
            if (m_awvalid && m_awready) out_beats++;
        end
        // bubbles: stall the sink for 8 clocks with the source offering, release, count idle output clocks in the next 16
        s_awvalid <= 1; m_awready <= 0; repeat (8) @(posedge aclk);
        m_awready <= 1; bubbles = 0;
        for (i = 0; i < 16; i++) begin @(posedge aclk); if (!m_awvalid) bubbles++; end
        $display("RESULT latency=%0d throughput_per_100=%0d bubbles_after_stall=%0d", lat, out_beats, bubbles);
        $finish;
    end
endmodule
